import itertools, random

def sat_solve(instance):
    m = instance["num_vars"]; clauses = instance["clauses"]
    for bits in itertools.product([False,True], repeat=m):
        ok = True
        for cl in clauses:
            if not any((lit>0) == bits[abs(lit)-1] for lit in cl):
                ok=False; break
        if ok: return True
    return False

def ds_solve(instance):
    n=instance["n"]; edges=instance["edges"]; k=instance["k"]
    if k<0: return False
    if k>=n: return True
    adj=[set() for _ in range(n)]
    for u,v in edges: adj[u].add(v); adj[v].add(u)
    for r in range(0,k+1):
        for comb in itertools.combinations(range(n),r):
            D=set(comb); dom=set(D)
            for u in D: dom|=adj[u]
            if len(dom)==n: return True
    return False

def lit_idx(lit):
    v=abs(lit)
    return 2*(v-1) + (0 if lit>0 else 1)

def reduce_D(instance):
    m=instance["num_vars"]; clauses=instance["clauses"]
    n=2*m; edges=[]
    for v in range(1,m+1):
        edges.append([2*(v-1),2*(v-1)+1])
    for cl in clauses:
        a=n; b=n+1; n+=2
        edges.append([a, lit_idx(cl[0])]); edges.append([a, lit_idx(cl[2])])
        edges.append([b, lit_idx(cl[1])]); edges.append([b, lit_idx(cl[2])])
    return {"n":n,"edges":edges,"k":m+len(clauses)}

def reduce_A(instance):
    # single clause vertex, k=n
    m=instance["num_vars"]; clauses=instance["clauses"]
    n=2*m; edges=[]
    for v in range(1,m+1):
        edges.append([2*(v-1),2*(v-1)+1])
    for cl in clauses:
        c=n; n+=1
        for lit in cl: edges.append([c, lit_idx(lit)])
    return {"n":n,"edges":edges,"k":m}

def reduce_tri(instance):
    # triangle clause gadget, k=n+m
    m=instance["num_vars"]; clauses=instance["clauses"]
    n=2*m; edges=[]
    for v in range(1,m+1):
        edges.append([2*(v-1),2*(v-1)+1])
    for cl in clauses:
        a,b,c=n,n+1,n+2; n+=3
        edges += [[a,b],[b,c],[a,c]]
        edges.append([a,lit_idx(cl[0])]); edges.append([b,lit_idx(cl[1])]); edges.append([c,lit_idx(cl[2])])
    return {"n":n,"edges":edges,"k":m+len(clauses)}

def reduce_indep(instance):
    # independent triple clause gadget, k=n+2m
    m=instance["num_vars"]; clauses=instance["clauses"]
    n=2*m; edges=[]
    for v in range(1,m+1):
        edges.append([2*(v-1),2*(v-1)+1])
    for cl in clauses:
        a,b,c=n,n+1,n+2; n+=3
        edges.append([a,lit_idx(cl[0])]); edges.append([b,lit_idx(cl[1])]); edges.append([c,lit_idx(cl[2])])
    return {"n":n,"edges":edges,"k":m+2*len(clauses)}

def all_clauses(m):
    res=[]
    for vars_ in itertools.combinations(range(1,m+1),3):
        for signs in itertools.product([1,-1],repeat=3):
            res.append([vars_[i]*signs[i] for i in range(3)])
    return res

def test_reduction(red, formulas):
    bad=[]
    for f in formulas:
        r=red(f)
        a=sat_solve(f); b=ds_solve(r)
        if a!=b:
            bad.append((f,a,b,r))
            if len(bad)>=5: break
    return bad

# exhaustive m=3
cl=all_clauses(3)
formulas=[]
for mask in range(1<<len(cl)):
    formulas.append({"num_vars":3,"clauses":[cl[i] for i in range(len(cl)) if mask>>i&1]})
# also m=0,1,2 no clauses
for m in [0,1,2]:
    formulas.append({"num_vars":m,"clauses":[]})

for name,red in [("A_single_k=n",reduce_A),("D_pair_k=n+m",reduce_D),("tri_k=n+m",reduce_tri),("indep_k=n+2m",reduce_indep)]:
    bad=test_reduction(red, formulas)
    print(name, "BAD count sample:", len(bad))
    for b in bad[:2]:
        print("   formula",b[0],"sat",b[1],"ds",b[2])
