                opts=[i]+[j for j in range(n) if (adj[i]>>j)&1]
                if bestopts is None or len(opts)<len(bestopts):
                    bestopts=opts; und=i
                    if len(opts)==1: break
            rem>>=1; i+=1
        # try options, order by coverage desc
        bestopts.sort(key=lambda v: bin(closed[v]&~dom).count('1'), reverse=True)
        for v in bestopts:
            if rec(dom|closed[v], count+1): return True
